import * as React from "react"
import type { ColumnFiltersState, OnChangeFn, PaginationState, SortingState, Updater } from "@tanstack/react-table"
import { debounce, parseAsArrayOf, parseAsIndex, parseAsInteger, parseAsString, useQueryStates } from "nuqs"

import { parseAsSort, type SortValue } from "@/lib/search-params"

type Options = {
  /** Column whose filter is the free-text search box → `?q=` */
  searchColumn?: string
  /** Columns with a single string filter (e.g. a status select) → `?<column>=paid` */
  filterColumns?: string[]
  /** Columns with a multi-select (faceted) filter → `?<column>=paid,shipped`; the filter value is a string[] */
  facetColumns?: string[]
  defaultSort?: SortValue
  pageSize?: number
  /** Prefix every key when a page has more than one table, e.g. "orders_" */
  prefix?: string
}

type FilterValue = string | string[]

const resolve = <T,>(updater: Updater<T>, old: T) =>
  typeof updater === "function" ? (updater as (old: T) => T)(old) : updater

/**
 * TanStack Table state (sorting, filters, pagination) kept in the URL with nuqs,
 * so refresh, back/forward and shared links all restore the same view.
 * Defaults are left out of the URL. Typing in search updates the URL after
 * 300 ms and replaces history; paging forward pushes history (Back = previous page).
 *
 * Needs `NuqsAdapter` (in components/providers.tsx) and, on prerendered
 * pages, a `<Suspense>` boundary above the table.
 */
export function useTableUrlState({
  searchColumn,
  filterColumns = [],
  facetColumns = [],
  defaultSort,
  pageSize = 10,
  prefix = "",
}: Options = {}) {
  const [state, setState] = useQueryStates(
    {
      q: parseAsString.withDefault(""),
      sort: defaultSort ? parseAsSort.withDefault(defaultSort) : parseAsSort,
      page: parseAsIndex.withDefault(0),
      size: parseAsInteger.withDefault(pageSize),
      ...Object.fromEntries(filterColumns.map((c) => [c, parseAsString])),
      ...Object.fromEntries(facetColumns.map((c) => [c, parseAsArrayOf(parseAsString)])),
    },
    {
      urlKeys: Object.fromEntries(
        ["q", "sort", "page", "size", ...filterColumns, ...facetColumns].map((k) => [k, prefix + k])
      ),
    }
  )

  const sorting: SortingState = React.useMemo(() => (state.sort ? [state.sort] : []), [state.sort])
  const pagination: PaginationState = React.useMemo(
    () => ({ pageIndex: state.page, pageSize: state.size }),
    [state.page, state.size]
  )

  // Rebuilt only when a filter value changes — a new array on every page change would
  // make TanStack think the filters changed and jump back to page 1.
  const values = state as Record<string, unknown>
  const filterEntries: [string, FilterValue][] = []
  if (searchColumn && state.q) filterEntries.push([searchColumn, state.q])
  for (const c of filterColumns) {
    const v = values[c]
    if (typeof v === "string" && v) filterEntries.push([c, v])
  }
  for (const c of facetColumns) {
    const v = values[c]
    if (Array.isArray(v) && v.length) filterEntries.push([c, v as string[]])
  }
  const filterKey = JSON.stringify(filterEntries)
  const columnFilters: ColumnFiltersState = React.useMemo(
    () => (JSON.parse(filterKey) as [string, FilterValue][]).map(([id, value]) => ({ id, value })),
    [filterKey]
  )

  const onSortingChange: OnChangeFn<SortingState> = (updater) => {
    const next = resolve(updater, sorting)[0]
    setState({ sort: next ? { id: next.id, desc: next.desc } : null })
  }

  const onPaginationChange: OnChangeFn<PaginationState> = (updater) => {
    const next = resolve(updater, pagination)
    if (next.pageIndex === pagination.pageIndex && next.pageSize === pagination.pageSize) return
    // Paging forward pushes history so Back returns to the previous page. Going to
    // page 1 replaces it: that's also what TanStack does on its own when data changes.
    setState({ page: next.pageIndex, size: next.pageSize }, { history: next.pageIndex > 0 ? "push" : "replace" })
  }

  const onColumnFiltersChange: OnChangeFn<ColumnFiltersState> = (updater) => {
    const next = resolve(updater, columnFilters)
    const find = (id: string) => next.find((f) => f.id === id)?.value
    const text = (id: string) => {
      const v = find(id)
      return typeof v === "string" && v ? v : null
    }
    const list = (id: string) => {
      const v = find(id)
      return Array.isArray(v) && v.length ? (v as string[]) : null
    }
    const q = searchColumn ? text(searchColumn) : null
    const typing = q !== (state.q || null)
    setState(
      {
        q,
        ...Object.fromEntries(filterColumns.map((c) => [c, text(c)])),
        ...Object.fromEntries(facetColumns.map((c) => [c, list(c)])),
        page: null, // any filter change starts from page 1
      },
      typing ? { limitUrlUpdates: debounce(300) } : undefined
    )
  }

  return { sorting, onSortingChange, columnFilters, onColumnFiltersChange, pagination, onPaginationChange }
}

/**
 * Ecsight formatters — the one place dates, money and relative times are
 * turned into Thai copy. `th-TH` uses the Buddhist calendar (พ.ศ.) and Arabic
 * digits by default; pass `era: "ce"` for ค.ศ.
 */

type Era = "be" | "ce"
type DateInput = Date | string | number

const localeFor = (era: Era) => (era === "ce" ? "th-TH-u-ca-gregory" : "th-TH")
const toDate = (d: DateInput) => (d instanceof Date ? d : new Date(d))

const dateStyles = {
  /** 1 ต.ค. 69 */
  short: { day: "numeric", month: "short", year: "2-digit" },
  /** 1 ต.ค. 2569 */
  medium: { day: "numeric", month: "short", year: "numeric" },
  /** 1 ตุลาคม 2569 */
  long: { day: "numeric", month: "long", year: "numeric" },
} satisfies Record<string, Intl.DateTimeFormatOptions>

export type DateStyle = keyof typeof dateStyles

export function formatDate(d: DateInput, { style = "medium", era = "be" }: { style?: DateStyle; era?: Era } = {}) {
  return toDate(d).toLocaleDateString(localeFor(era), dateStyles[style])
}

/** "1–7 ต.ค. 2569", "28 ก.ย. – 4 ต.ค. 2569" — collapses shared month/year. */
export function formatDateRange(from: DateInput, to: DateInput, { era = "be" }: { era?: Era } = {}) {
  return new Intl.DateTimeFormat(localeFor(era), dateStyles.medium).formatRange(toDate(from), toDate(to))
}

/** 14:05 */
export function formatTime(d: DateInput) {
  return toDate(d).toLocaleTimeString("th-TH", { hour: "2-digit", minute: "2-digit" })
}

const thb = new Intl.NumberFormat("th-TH", { style: "currency", currency: "THB", maximumFractionDigits: 0 })
const thbSatang = new Intl.NumberFormat("th-TH", { style: "currency", currency: "THB", minimumFractionDigits: 2 })

/** ฿1,284,500 — pass `satang: true` for ฿1,284,500.00 */
export function formatTHB(n: number, { satang = false }: { satang?: boolean } = {}) {
  return (satang ? thbSatang : thb).format(n)
}

const relative = new Intl.RelativeTimeFormat("th", { numeric: "auto" })
const units: [Intl.RelativeTimeFormatUnit, number][] = [
  ["year", 31_536_000],
  ["month", 2_592_000],
  ["week", 604_800],
  ["day", 86_400],
  ["hour", 3_600],
  ["minute", 60],
]

/** "3 นาทีที่ผ่านมา", "เมื่อวาน", "ในอีก 2 วัน"; under a minute → "เมื่อสักครู่". */
export function formatRelative(d: DateInput, now: DateInput = Date.now()) {
  const seconds = (toDate(d).getTime() - toDate(now).getTime()) / 1000
  for (const [unit, size] of units) {
    if (Math.abs(seconds) >= size) return relative.format(Math.round(seconds / size), unit)
  }
  return "เมื่อสักครู่"
}

/* ─── Date ↔ string for APIs and inputs ──────────────────────────────── */

const pad = (n: number) => String(n).padStart(2, "0")

/**
 * "2026-10-01" from the **local** calendar day. Use this for API payloads and
 * URLs — `date.toISOString()` goes through UTC, so local midnight in Thailand
 * (UTC+7) would come out as the previous day.
 */
export function toISODate(d: Date) {
  return `${d.getFullYear()}-${pad(d.getMonth() + 1)}-${pad(d.getDate())}`
}

/** "2026-10-01" → local midnight (not UTC, unlike `new Date("2026-10-01")`). Invalid → undefined. */
export function parseISODate(s: string) {
  const m = /^(\d{4})-(\d{2})-(\d{2})$/.exec(s)
  return m ? safeDate(Number(m[1]), Number(m[2]), Number(m[3])) : undefined
}

function safeDate(y: number, m: number, d: number) {
  const date = new Date(y, m - 1, d)
  return date.getFullYear() === y && date.getMonth() === m - 1 && date.getDate() === d ? date : undefined
}

// Thai month names as Intl prints them — short ("ต.ค.") and long ("ตุลาคม"), dots optional
const thaiMonths = Array.from({ length: 12 }, (_, m) => {
  const d = new Date(2026, m, 1)
  return [d.toLocaleDateString("th-TH", { month: "short" }), d.toLocaleDateString("th-TH", { month: "long" })].map(
    (s) => s.replace(/\./g, "")
  )
})

/** Resolve a typed year: ≥ 2400 is พ.ศ.; 2 digits follow `era` (69 → 2569 → 2026, or 26 → 2026). */
function toCE(year: string, era: Era) {
  const y = Number(year)
  if (year.length <= 2) return era === "be" ? 2500 + y - 543 : 2000 + y
  return y >= 2400 ? y - 543 : y
}

/**
 * Parse what people actually type into a date field. Accepts Thai or Arabic
 * digits, พ.ศ. or ค.ศ. (a 4-digit year ≥ 2400 is พ.ศ.), and:
 * `1/10/2569` · `01-10-69` · `1.10.2026` · `01102569` · `1 ต.ค. 2569` · `1 ตุลาคม 69` · `2026-10-01`.
 * Returns local midnight, or undefined when the text isn't a real date.
 */
export function parseThaiDate(input: string, { era = "be" }: { era?: Era } = {}): Date | undefined {
  const s = input
    .trim()
    .replace(/[๐-๙]/g, (c) => String(c.charCodeAt(0) - 0x0e50))
    .replace(/\s+/g, " ")
  if (!s) return undefined

  const iso = parseISODate(s)
  if (iso) return iso

  let m = /^(\d{1,2})[/\-. ](\d{1,2})[/\-. ](\d{2}|\d{4})$/.exec(s)
  if (m) return safeDate(toCE(m[3], era), Number(m[2]), Number(m[1]))

  m = /^(\d{2})(\d{2})(\d{2}|\d{4})$/.exec(s)
  if (m) return safeDate(toCE(m[3], era), Number(m[2]), Number(m[1]))

  m = /^(\d{1,2}) ?([ก-๛.]+) ?(\d{2}|\d{4})$/.exec(s)
  if (m) {
    const name = m[2].replace(/\./g, "")
    const month = thaiMonths.findIndex((names) => names.includes(name))
    if (month >= 0) return safeDate(toCE(m[3], era), month + 1, Number(m[1]))
  }
  return undefined
}

import { createParser } from "nuqs"

import { parseISODate, toISODate } from "@/lib/format"

/**
 * URL search-param parsers for nuqs.
 *
 * `parseAsLocalDate` — `?from=2026-09-01` ↔ local midnight. Use this instead of
 * nuqs' `parseAsIsoDate`, which goes through UTC: in Thailand (UTC+7) local
 * 1 Oct 00:00 would serialise as "2026-09-30".
 */
export const parseAsLocalDate = createParser<Date>({
  parse: (v) => parseISODate(v) ?? null,
  serialize: toISODate,
  eq: (a, b) => a.getTime() === b.getTime(),
})

export type SortValue = { id: string; desc: boolean }

/** `?sort=date.desc` ↔ `{ id: "date", desc: true }` (one column — what a TanStack table sorts by) */
export const parseAsSort = createParser<SortValue>({
  parse: (v) => {
    const m = /^([\w-]+)\.(asc|desc)$/.exec(v)
    return m ? { id: m[1], desc: m[2] === "desc" } : null
  },
  serialize: (s) => `${s.id}.${s.desc ? "desc" : "asc"}`,
  eq: (a, b) => a.id === b.id && a.desc === b.desc,
})
